<?php
/**
 * IWS Variation Swatches.
 */

if ( ! defined( 'ABSPATH' ) ) { exit; }

add_action( 'admin_menu', 'iws_swatches_admin_menu', 61 );
add_action( 'admin_init', 'iws_swatches_register_settings' );
add_action( 'init', 'iws_swatches_init', 20 );
add_action( 'wp_enqueue_scripts', 'iws_swatches_assets' );

function iws_swatches_defaults() {
	return array( 'enabled'=>'yes', 'display_mode'=>'auto', 'max_buttons'=>12, 'large_columns'=>4, 'labels_on_top'=>'yes', 'style'=>'compact', 'color_shape'=>'round', 'image_shape'=>'rounded', 'show_labels'=>'yes', 'color_attrs'=>'color,colour', 'image_attrs'=>'', 'button_attrs'=>'material', 'select_attrs'=>'size,dimension,dimensions', 'fallback_colors'=>"High Visibility Yellow = #c8d858\nSafety Yellow = #e6a910" );
}
function iws_swatches_get_settings() { return wp_parse_args( get_option( 'iws_variation_swatches_settings', array() ), iws_swatches_defaults() ); }
function iws_swatches_admin_menu() { add_submenu_page( 'woocommerce', __( 'Variation Swatches', 'wp-theme-woo-support' ), __( 'Variation Swatches', 'wp-theme-woo-support' ), 'manage_woocommerce', 'iws-variation-swatches', 'iws_swatches_settings_page' ); }
function iws_swatches_register_settings() { register_setting( 'iws_variation_swatches_group', 'iws_variation_swatches_settings', 'iws_swatches_sanitize_settings' ); }
function iws_swatches_sanitize_settings( $input ) { $d=iws_swatches_defaults(); $o=array(); foreach($d as $k=>$v){ if(in_array($k,array('enabled','show_labels','labels_on_top'),true)){$o[$k]=!empty($input[$k])?'yes':'no';} elseif('max_buttons'===$k){$o[$k]=max(0,absint($input[$k]??$v));} elseif('large_columns'===$k){$cols=absint($input[$k]??$v);$o[$k]=in_array($cols,array(4,5),true)?$cols:4;} elseif('fallback_colors'===$k){$lines=preg_split('/\r\n|\r|\n/',(string)($input[$k]??$v));$clean=array();foreach((array)$lines as $line){$line=trim(wp_strip_all_tags($line));if(''===$line){continue;}if(!preg_match('/^(.+?)(?:=|:)(.+)$/',$line,$m)){continue;}$name=sanitize_text_field(trim($m[1]));$color=iws_swatches_normalize_color(trim($m[2]));if($name&&$color){$clean[]=$name.' = '.$color;}}$o[$k]=implode("\n",$clean);} elseif('display_mode'===$k){$o[$k]=in_array($input[$k]??'auto',array('auto','always_buttons','always_select'),true)?$input[$k]:'auto';} elseif('style'===$k){$o[$k]=in_array($input[$k]??'compact',array('compact','comfortable','minimal'),true)?$input[$k]:'compact';} elseif(in_array($k,array('color_shape','image_shape'),true)){$o[$k]=in_array($input[$k]??'round',array('round','rounded','square'),true)?$input[$k]:'round';} else {$o[$k]=sanitize_text_field($input[$k]??$v);} } return $o; }
function iws_swatches_settings_page(){ $s=iws_swatches_get_settings(); ?>
<div class="wrap"><h1><?php esc_html_e('Variation Swatches','wp-theme-woo-support'); ?></h1><p><?php esc_html_e('Choose auto/select/button behavior and compact styling for large variation products.','wp-theme-woo-support'); ?></p><form method="post" action="options.php"><?php settings_fields('iws_variation_swatches_group'); ?><div class="postbox"><div class="inside"><table class="form-table" role="presentation">
<tr><th><?php esc_html_e('Enable','wp-theme-woo-support'); ?></th><td><label><input type="checkbox" name="iws_variation_swatches_settings[enabled]" value="1" <?php checked($s['enabled'],'yes'); ?>> <?php esc_html_e('Active','wp-theme-woo-support'); ?></label></td></tr>
<tr><th><?php esc_html_e('Display mode','wp-theme-woo-support'); ?></th><td><select name="iws_variation_swatches_settings[display_mode]"><option value="auto" <?php selected($s['display_mode'],'auto'); ?>><?php esc_html_e('Auto: buttons until max, then select','wp-theme-woo-support'); ?></option><option value="always_buttons" <?php selected($s['display_mode'],'always_buttons'); ?>><?php esc_html_e('Always buttons/swatches','wp-theme-woo-support'); ?></option><option value="always_select" <?php selected($s['display_mode'],'always_select'); ?>><?php esc_html_e('Always select dropdowns','wp-theme-woo-support'); ?></option></select></td></tr>
<tr><th><?php esc_html_e('Max buttons in Auto','wp-theme-woo-support'); ?></th><td><input type="number" min="0" class="small-text" name="iws_variation_swatches_settings[max_buttons]" value="<?php echo esc_attr($s['max_buttons']); ?>"> <span class="description"><?php esc_html_e('0 = unlimited. Recommended 8-16.','wp-theme-woo-support'); ?></span></td></tr>
<tr><th><?php esc_html_e('Large list columns','wp-theme-woo-support'); ?></th><td><select name="iws_variation_swatches_settings[large_columns]"><option value="4" <?php selected(absint($s['large_columns']),4); ?>><?php esc_html_e('4 per row (24% width)','wp-theme-woo-support'); ?></option><option value="5" <?php selected(absint($s['large_columns']),5); ?>><?php esc_html_e('5 per row (19% width)','wp-theme-woo-support'); ?></option></select> <span class="description"><?php esc_html_e('Used when an attribute has more than 12 swatch buttons. Choose 5 per row for tighter lists.','wp-theme-woo-support'); ?></span></td></tr>
<tr><th><?php esc_html_e('Labels above buttons','wp-theme-woo-support'); ?></th><td><label><input type="checkbox" name="iws_variation_swatches_settings[labels_on_top]" value="1" <?php checked($s['labels_on_top'],'yes'); ?>> <?php esc_html_e('Move variation row labels above swatch buttons for more horizontal space.','wp-theme-woo-support'); ?></label></td></tr>
<tr><th><?php esc_html_e('Button style','wp-theme-woo-support'); ?></th><td><select name="iws_variation_swatches_settings[style]"><option value="compact" <?php selected($s['style'],'compact'); ?>>Compact</option><option value="comfortable" <?php selected($s['style'],'comfortable'); ?>>Comfortable</option><option value="minimal" <?php selected($s['style'],'minimal'); ?>>Minimal</option></select></td></tr>
<tr><th><?php esc_html_e('Color shape','wp-theme-woo-support'); ?></th><td><select name="iws_variation_swatches_settings[color_shape]"><option value="round" <?php selected($s['color_shape'],'round'); ?>>Round</option><option value="rounded" <?php selected($s['color_shape'],'rounded'); ?>>Rounded</option><option value="square" <?php selected($s['color_shape'],'square'); ?>>Square</option></select></td></tr>
<tr><th><?php esc_html_e('Image shape','wp-theme-woo-support'); ?></th><td><select name="iws_variation_swatches_settings[image_shape]"><option value="rounded" <?php selected($s['image_shape'],'rounded'); ?>>Rounded</option><option value="round" <?php selected($s['image_shape'],'round'); ?>>Round</option><option value="square" <?php selected($s['image_shape'],'square'); ?>>Square</option></select></td></tr>
<tr><th><?php esc_html_e('Show button labels','wp-theme-woo-support'); ?></th><td><label><input type="checkbox" name="iws_variation_swatches_settings[show_labels]" value="1" <?php checked($s['show_labels'],'yes'); ?>> <?php esc_html_e('Show labels on normal buttons','wp-theme-woo-support'); ?></label></td></tr>
<tr><th><?php esc_html_e('Color attributes','wp-theme-woo-support'); ?></th><td><input type="text" class="regular-text" name="iws_variation_swatches_settings[color_attrs]" value="<?php echo esc_attr($s['color_attrs']); ?>"></td></tr>
<tr><th><?php esc_html_e('Image attributes','wp-theme-woo-support'); ?></th><td><input type="text" class="regular-text" name="iws_variation_swatches_settings[image_attrs]" value="<?php echo esc_attr($s['image_attrs']); ?>"></td></tr>
<tr><th><?php esc_html_e('Button attributes','wp-theme-woo-support'); ?></th><td><input type="text" class="regular-text" name="iws_variation_swatches_settings[button_attrs]" value="<?php echo esc_attr($s['button_attrs']); ?>"></td></tr>
<tr><th><?php esc_html_e('Always select attributes','wp-theme-woo-support'); ?></th><td><input type="text" class="regular-text" name="iws_variation_swatches_settings[select_attrs]" value="<?php echo esc_attr($s['select_attrs']); ?>"><p class="description"><?php esc_html_e('Useful for huge Size/Dimension lists. Ignored if Display mode is Always buttons.','wp-theme-woo-support'); ?></p></td></tr>
<tr><th><?php esc_html_e('Fallback swatch colours','wp-theme-woo-support'); ?></th><td><textarea class="large-text code" rows="5" name="iws_variation_swatches_settings[fallback_colors]"><?php echo esc_textarea($s['fallback_colors']); ?></textarea><p class="description"><?php esc_html_e('One colour per line, for variation options without WooCommerce term colour data. Example: High Visibility Yellow = #c8d858','wp-theme-woo-support'); ?></p></td></tr>
</table><?php submit_button(__('Save swatch settings','wp-theme-woo-support')); ?></div></div></form></div><?php }
function iws_swatches_init(){ $s=iws_swatches_get_settings(); if('yes'!==$s['enabled']){return;} add_filter('woocommerce_dropdown_variation_attribute_options_html','iws_swatches_dropdown_html',30,2); iws_swatches_register_term_meta_hooks(); }
function iws_swatches_register_term_meta_hooks(){ if(!function_exists('wc_get_attribute_taxonomies')){return;} foreach((array)wc_get_attribute_taxonomies() as $tax){ $taxonomy=wc_attribute_taxonomy_name($tax->attribute_name); add_action($taxonomy.'_add_form_fields','iws_swatches_add_term_fields'); add_action($taxonomy.'_edit_form_fields','iws_swatches_edit_term_fields'); add_action('created_'.$taxonomy,'iws_swatches_save_term_fields'); add_action('edited_'.$taxonomy,'iws_swatches_save_term_fields'); } }
function iws_swatches_add_term_fields(){ ?><div class="form-field"><label><?php esc_html_e('Swatch color','wp-theme-woo-support'); ?></label><input type="text" name="iws_swatch_color" placeholder="#cccccc, #111111, gold"><p class="description"><?php esc_html_e('For multi-colour swatches, separate 2 or more colours with commas, e.g. #ffffff, #111111, gold.','wp-theme-woo-support'); ?></p></div><div class="form-field"><label><?php esc_html_e('Swatch image URL','wp-theme-woo-support'); ?></label><input type="url" name="iws_swatch_image_url" placeholder="https://"></div><?php }
function iws_swatches_edit_term_fields($term){ ?><tr class="form-field"><th><label><?php esc_html_e('Swatch color','wp-theme-woo-support'); ?></label></th><td><input type="text" name="iws_swatch_color" value="<?php echo esc_attr(get_term_meta($term->term_id,'iws_swatch_color',true)); ?>" placeholder="#cccccc, #111111, gold"><p class="description"><?php esc_html_e('For multi-colour swatches, separate 2 or more colours with commas, e.g. #ffffff, #111111, gold.','wp-theme-woo-support'); ?></p></td></tr><tr class="form-field"><th><label><?php esc_html_e('Swatch image URL','wp-theme-woo-support'); ?></label></th><td><input type="url" name="iws_swatch_image_url" value="<?php echo esc_url(get_term_meta($term->term_id,'iws_swatch_image_url',true)); ?>" placeholder="https://"></td></tr><?php }
function iws_swatches_save_term_fields($term_id){ if(isset($_POST['iws_swatch_color'])){ update_term_meta($term_id,'iws_swatch_color',sanitize_text_field(wp_unslash($_POST['iws_swatch_color']))); } if(isset($_POST['iws_swatch_image_url'])){ update_term_meta($term_id,'iws_swatch_image_url',esc_url_raw(wp_unslash($_POST['iws_swatch_image_url']))); } }
function iws_swatches_assets(){ wp_enqueue_script('jquery'); wp_register_style('iws-variation-swatches',false,array(),'2.0.0'); wp_enqueue_style('iws-variation-swatches'); wp_add_inline_style('iws-variation-swatches',iws_swatches_css()); }
function iws_swatches_css(){ $s=iws_swatches_get_settings(); $cols=in_array(absint($s['large_columns']??4),array(4,5),true)?absint($s['large_columns']):4; $basis=round(100/$cols,3); $max=5===$cols?'19%':'24%'; return '.iws-variation-swatches{display:flex!important;flex-wrap:wrap!important;justify-content:flex-start!important;align-items:stretch!important;gap:6px!important;margin:8px 0 6px!important;width:100%!important;max-width:100%!important;clear:both!important}.iws-swatch{display:inline-flex!important;align-items:center!important;justify-content:center!important;min-height:32px!important;min-width:32px!important;max-width:100%!important;padding:5px 10px!important;border:1px solid #cbd5e1!important;border-radius:8px!important;background:#fff;color:#111827;cursor:pointer;font-size:12px!important;font-weight:600!important;line-height:1.1!important;text-align:center!important;white-space:normal!important;overflow-wrap:anywhere!important;word-break:normal!important;box-shadow:0 1px 2px rgba(15,23,42,.05)!important;transition:.15s ease}.iws-swatches-large .iws-swatch{flex:0 1 calc('.$basis.'% - 6px)!important;max-width:'.$max.'!important;min-width:0!important}.iws-swatches-large .iws-swatch.iws-swatch-long{width:auto!important}.iws-swatches-large.iws-swatches-super-large .iws-swatch{font-size:11px!important;padding-left:6px!important;padding-right:6px!important}.variations tr.iws-swatches-label-top{display:block!important;margin-bottom:10px!important}.variations tr.iws-swatches-label-top th.label,.variations tr.iws-swatches-label-top td.value{display:block!important;width:100%!important;max-width:100%!important;padding-left:0!important;padding-right:0!important;text-align:left!important}.variations tr.iws-swatches-label-top th.label label{display:block!important;margin:0 0 6px!important}.iws-swatch:hover{border-color:#111827!important;box-shadow:0 0 0 2px rgba(17,24,39,.12),0 4px 10px rgba(15,23,42,.10)!important}.iws-swatch.selected{border-color:#111827!important;box-shadow:0 0 0 2px #fff,0 0 0 5px rgba(17,24,39,.28),0 8px 18px rgba(15,23,42,.18)!important;transform:translateY(-1px)!important}.iws-swatch-color.selected{box-shadow:0 0 0 2px #fff,0 0 0 5px rgba(17,24,39,.35),0 8px 18px rgba(15,23,42,.20)!important}.iws-swatches-comfortable .iws-swatch{min-height:38px!important;min-width:38px!important;padding:7px 12px!important;font-size:13px!important}.iws-swatches-minimal .iws-swatch{box-shadow:none!important;background:#f8fafc!important}.iws-swatch-color{padding:0!important;width:30px!important;height:30px!important;border-radius:999px!important;overflow:visible!important;flex:0 0 30px!important;position:relative!important}.iws-swatch-image{padding:0!important;width:42px!important;height:42px!important;border-radius:10px!important;background-size:cover!important;background-position:center!important;flex:0 0 42px!important;overflow:visible!important;position:relative!important}.iws-swatch-color span,.iws-swatch-image span{position:absolute!important;left:50%!important;top:-42px!important;z-index:50!important;display:none!important;width:max-content!important;max-width:180px!important;height:auto!important;min-height:0!important;padding:6px 8px!important;overflow:visible!important;clip:auto!important;transform:translateX(-50%)!important;border-radius:4px!important;background:#111827!important;color:#fff!important;font-size:11px!important;font-weight:600!important;line-height:1.25!important;text-align:center!important;white-space:normal!important;pointer-events:none!important;box-shadow:0 8px 18px rgba(15,23,42,.2)!important}.iws-swatch-color span:after,.iws-swatch-image span:after{content:"";position:absolute;left:50%;bottom:-5px;width:10px;height:10px;transform:translateX(-50%) rotate(45deg);background:#111827}.iws-swatch-color:hover span,.iws-swatch-color:focus span,.iws-swatch-color:focus-visible span,.iws-swatch-image:hover span,.iws-swatch-image:focus span,.iws-swatch-image:focus-visible span{display:block!important}.iws-shape-square{border-radius:3px!important}.iws-shape-rounded{border-radius:9px!important}.iws-shape-round{border-radius:999px!important}.variations select.iws-hidden-select,.variations select.iws-hidden-select+.select2,.variations select.iws-hidden-select~.select2,.iws-hidden-select2{display:none!important;visibility:hidden!important;opacity:0!important;width:0!important;height:0!important;min-width:0!important;min-height:0!important;margin:0!important;padding:0!important;border:0!important;overflow:hidden!important}@media(max-width:640px){.iws-swatches-large .iws-swatch{flex-basis:calc(50% - 6px)!important;max-width:calc(50% - 6px)!important}}'; }
function iws_swatches_hide_select_html($html){ if(false!==strpos($html,'iws-hidden-select')){return $html;} $with_class=preg_replace('/<select([^>]*)class=(["\'])(.*?)(\2)/i','<select$1class=$2$3 iws-hidden-select$4',$html,1,$count); if($count){return $with_class;} return preg_replace('/<select\b/i','<select class="iws-hidden-select"',$html,1); }
function iws_swatches_dropdown_html($html,$args){ $s=iws_swatches_get_settings(); if(empty($args['options'])||empty($args['attribute'])||empty($args['product'])){return $html;} $options=$args['options']; $attribute=sanitize_title($args['attribute']); $type=iws_swatches_get_type($attribute,$s); if('always_select'===$s['display_mode']||('select'===$type&&'always_buttons'!==$s['display_mode'])){return $html;} if('auto'===$s['display_mode']&&absint($s['max_buttons'])>0&&count($options)>absint($s['max_buttons'])){return $html;} $html=iws_swatches_hide_select_html($html); $option_count=count($options); $wrap_classes=array('iws-variation-swatches','iws-swatches-'.$s['style']); if($option_count>12){$wrap_classes[]='iws-swatches-large';} if($option_count>33){$wrap_classes[]='iws-swatches-super-large';} $out='<div class="'.esc_attr(implode(' ',$wrap_classes)).'" data-attribute_name="attribute_'.esc_attr($attribute).'" data-display_mode="'.esc_attr($s['display_mode']).'" data-option_count="'.esc_attr($option_count).'" data-labels_top="'.esc_attr($s['labels_on_top']).'">'; foreach($options as $option){ $term=false; if(taxonomy_exists($args['attribute'])){$term=get_term_by('slug',$option,$args['attribute']);} $label=($term&&!is_wp_error($term))?$term->name:$option; $class='iws-swatch'; $label_len=function_exists('mb_strlen')?mb_strlen(wp_strip_all_tags((string)$label)):strlen(wp_strip_all_tags((string)$label)); if($label_len>28){$class.=' iws-swatch-long';} $style=''; if('color'===$type){$class.=' iws-swatch-color iws-shape-'.sanitize_html_class($s['color_shape']); $style=iws_swatches_get_color_style($term,$option);} elseif('image'===$type){$img=iws_swatches_get_image($term); $class.=' iws-swatch-image iws-shape-'.sanitize_html_class($s['image_shape']); if($img){$style=' style="background-image:url('.esc_url($img).');"';}} $text=('yes'===$s['show_labels']||in_array($type,array('color','image'),true))?'<span>'.esc_html($label).'</span>':''; $out.='<button type="button" class="'.esc_attr($class).'" data-value="'.esc_attr($option).'" aria-label="'.esc_attr($label).'"'.$style.'>'.$text.'</button>'; } $out.='</div><script>(function(){if(window.iwsVariationSwatchesBound){if(window.iwsInitVariationSwatches){window.iwsInitVariationSwatches(document);}return;}window.iwsVariationSwatchesBound=true;function forceHide(el){if(!el)return;el.classList.add("iws-hidden-select2");el.style.setProperty("display","none","important");el.style.setProperty("visibility","hidden","important");el.style.setProperty("opacity","0","important");el.style.setProperty("width","0","important");el.style.setProperty("height","0","important");el.style.setProperty("min-width","0","important");el.style.setProperty("min-height","0","important");el.style.setProperty("margin","0","important");el.style.setProperty("padding","0","important");el.style.setProperty("border","0","important");el.style.setProperty("overflow","hidden","important");}function hideSelectUi(s){forceHide(s);var n=s?s.nextElementSibling:null;while(n&&n.classList&&n.classList.contains("select2")){forceHide(n);n=n.nextElementSibling;}if(s&&s.id){var x=document.querySelector(".select2[aria-labelledby=\'select2-"+s.id+"-container\']");forceHide(x?x.closest(".select2"):null);}}function clearSelected(scope){(scope||document).querySelectorAll(".iws-swatch.selected").forEach(function(b){b.classList.remove("selected");});}function clearInitialVariationValues(ctx){(ctx||document).querySelectorAll("form.variations_form").forEach(function(form){if(form.dataset.iwsInitialVariationCleared==="yes"){return;}form.dataset.iwsInitialVariationCleared="yes";clearSelected(form);form.querySelectorAll("select[name^=\'attribute_\']").forEach(function(select){if(!select.value){return;}select.value="";select.selectedIndex=-1;select.dispatchEvent(new Event("change",{bubbles:true}));if(window.jQuery){window.jQuery(select).val("").trigger("change");}});if(window.jQuery){window.jQuery(form).trigger("reset_data");}});}function sync(w){var c=w.closest("td")||w.parentNode;var s=c.querySelector("select[name=\'"+w.dataset.attribute_name+"\']");if(s){s.classList.add("iws-hidden-select");hideSelectUi(s);w.querySelectorAll(".iws-swatch").forEach(function(b){b.classList.toggle("selected",b.dataset.value===s.value&&s.value!=="");});}if(w.dataset.labels_top==="yes"){var r=w.closest("tr");if(r){r.classList.add("iws-swatches-label-top");}}var f=w.closest("form.variations_form");if(f&&w.dataset.display_mode==="always_buttons"){f.classList.add("iws-swatches-always-buttons");}}function init(ctx){clearInitialVariationValues(ctx||document);(ctx||document).querySelectorAll(".iws-variation-swatches").forEach(sync);}window.iwsInitVariationSwatches=init;document.addEventListener("click",function(e){var clear=e.target.closest(".reset_variations");if(clear){var form=clear.closest("form.variations_form")||document;clearSelected(form);}var btn=e.target.closest(".iws-swatch");if(!btn)return;var wrap=btn.closest(".iws-variation-swatches");if(!wrap)return;var cell=wrap.closest("td")||wrap.parentNode;var select=cell.querySelector("select[name=\'"+wrap.dataset.attribute_name+"\']");if(!select)return;select.value=btn.dataset.value;select.dispatchEvent(new Event("change",{bubbles:true}));if(window.jQuery){window.jQuery(select).trigger("change");}wrap.querySelectorAll(".iws-swatch").forEach(function(b){b.classList.remove("selected")});btn.classList.add("selected");sync(wrap);});document.addEventListener("DOMContentLoaded",function(){init(document);});if(window.jQuery){window.jQuery(document.body).on("woocommerce_update_variation_values found_variation",function(){init(document);}).on("reset_data hide_variation",function(e){var form=e&&e.target?e.target:document;clearSelected(form);init(document);});}if("MutationObserver" in window){new MutationObserver(function(){init(document);}).observe(document.documentElement,{childList:true,subtree:true});}init(document);})();</script>'; return $html.$out; }
function iws_swatches_get_type($attribute,$s){ $name=str_replace('pa_','',sanitize_title($attribute)); foreach(array('select_attrs'=>'select','color_attrs'=>'color','image_attrs'=>'image','button_attrs'=>'button') as $setting=>$type){ $list=array_filter(array_map('sanitize_title',array_map('trim',explode(',',$s[$setting])))); if(in_array($name,$list,true)||in_array($attribute,$list,true)){return $type;} } return 'button'; }
function iws_swatches_color_map(){ return array('black'=>'#111827','white'=>'#fff','red'=>'#dc2626','blue'=>'#2563eb','green'=>'#16a34a','yellow'=>'#facc15','high-visibility-yellow'=>'#c8d858','safety-yellow'=>'#e6a910','grey'=>'#6b7280','gray'=>'#6b7280','silver'=>'#c0c0c0','gold'=>'#d4af37','orange'=>'#f97316','brown'=>'#92400e','purple'=>'#7c3aed','blue-alt'=>'#2563eb','navy'=>'#1e3a8a','cream'=>'#f5f5dc','beige'=>'#d6c6a8'); }
function iws_swatches_fallback_color_map(){ $settings=iws_swatches_get_settings(); $map=array(); $base=iws_swatches_color_map(); $lines=preg_split('/\r\n|\r|\n/',(string)($settings['fallback_colors']??'')); foreach((array)$lines as $line){ if(!preg_match('/^(.+?)(?:=|:)(.+)$/',trim($line),$m)){continue;} $raw=trim($m[2]); $key=sanitize_title($raw); $color=''; if(preg_match('/^#([a-f0-9]{3}|[a-f0-9]{6})$/i',$raw)||preg_match('/^(rgb|rgba|hsl|hsla)\([0-9.,%\s]+\)$/i',$raw)){$color=$raw;} elseif(isset($base[$key])){$color=$base[$key];} if($color){$map[sanitize_title(trim($m[1]))]=$color;} } return $map; }
function iws_swatches_normalize_color($color){ $color=trim((string)$color); if(''===$color){return '';} if(preg_match('/^#([a-f0-9]{3}|[a-f0-9]{6})$/i',$color)){return $color;} if(preg_match('/^(rgb|rgba|hsl|hsla)\([0-9.,%\s]+\)$/i',$color)){return $color;} $custom=iws_swatches_fallback_color_map(); $key=sanitize_title($color); if(isset($custom[$key])){return $custom[$key];} $map=iws_swatches_color_map(); return $map[$key]??''; }
function iws_swatches_get_color_values($term,$fallback){ $raw=''; if($term&&!is_wp_error($term)){ $raw=get_term_meta($term->term_id,'iws_swatch_color',true); if(!$raw){$raw=get_term_meta($term->term_id,'color',true);} } if(!$raw){$raw=$fallback;} $raw_key=sanitize_title((string)$raw); $fallback_key=sanitize_title((string)$fallback); if(in_array($raw_key,array('mixed','mix','multi','multiple','assorted'),true)||in_array($fallback_key,array('mixed','mix','multi','multiple','assorted'),true)){ return array('#dc2626','#facc15','#2563eb','#16a34a','#111827','#fff'); } $parts=preg_split('/\s*(?:,|\||\/|\+|&|-|\band\b)\s*/i',(string)$raw); $colors=array(); foreach((array)$parts as $part){ $color=iws_swatches_normalize_color($part); if($color){$colors[]=$color;} } if(empty($colors)){ $single=iws_swatches_normalize_color($fallback); $colors[]=$single?$single:'#e5e7eb'; } return array_values(array_unique($colors)); }
function iws_swatches_get_color($term,$fallback){ $colors=iws_swatches_get_color_values($term,$fallback); return $colors[0]??'#e5e7eb'; }
function iws_swatches_get_color_style($term,$fallback){ $colors=iws_swatches_get_color_values($term,$fallback); if(count($colors)<2){ return ' style="background-color:'.esc_attr($colors[0]??'#e5e7eb').';"'; } $stops=array(); $total=count($colors); foreach($colors as $i=>$color){ $start=round(($i/$total)*100,3); $end=round((($i+1)/$total)*100,3); $safe=esc_attr($color); $stops[]=$safe.' '.$start.'%'; $stops[]=$safe.' '.$end.'%'; } return ' style="background:linear-gradient(135deg,'.implode(',',$stops).');"'; }
function iws_swatches_get_image($term){ if(!$term||is_wp_error($term)){return '';} $url=get_term_meta($term->term_id,'iws_swatch_image_url',true); if($url){return $url;} $id=absint(get_term_meta($term->term_id,'thumbnail_id',true)); return $id?wp_get_attachment_image_url($id,'thumbnail'):''; }
